def _moment_tuple_all_zero(moments):
    """判断 8 项矩 tuple 的全部叶是否恰为 0.0（值为零即视为零矩）。"""
    for tree in moments:
        stack = [tree]
        while stack:
            node = stack.pop()
            if isinstance(node, list):
                stack.extend(node)
            elif node != 0.0:
                return False
    return True


