def _parse_deep_adam_state(node, n_samples, epochs, microbatch_size,
                           accum_steps, param_refs):
    """解析 state JSON 数组并完整按训练函数契约校验，返回全新 tuple。

    四元 (epoch, order, cursor, rng) 更新边界态或八元微批边界态。
    校验规则全部沿用 train_deep_adam_accum_batches：epoch 满足
    0 <= epoch <= epochs、rng 为 uint32、order 为空时 cursor==0，
    非空时为 0..N-1 全排列；四元态 cursor 为更新边界，八元态 cursor
    为微批边界且四个累计字段与游标/相互关系一致。八元态的
    pending_grads 八棵树与 param_refs 八组参数同形、叶为有限
    int/float。返回 list/tuple 均为全新对象，不与 JSON 文档别名。
    """
    if not isinstance(node, list):
        raise TypeError(
            "state 必须是 JSON 数组，得到 %s" % type(node).__name__
        )
    if len(node) not in _CKPT_DEEP_ADAM_STATE_ARITY:
        raise ValueError(
            "state 必须恰含 4 项（更新边界）或 8 项（微批边界），"
            "得到 %d 项" % len(node)
        )
    epoch = _parse_json_int(node[0], "state 的 epoch")
    if epoch < 0 or epoch > epochs:
        raise ValueError(
            "state 的 epoch 必须满足 0 <= epoch <= epochs（%d）" % epochs
        )
    order_node = node[1]
    if not isinstance(order_node, list):
        raise TypeError(
            "state 的 order 必须是 JSON 数组，得到 %s"
            % type(order_node).__name__
        )
    order = []
    for value in order_node:
        order.append(_parse_json_int(value, "state 的 order 成员"))
    cursor = _parse_json_int(node[2], "state 的 cursor")
    rng = _parse_json_uint32(node[3], "state 的 rng")
    group_span = microbatch_size * accum_steps

    if len(order) == 0:
        if cursor != 0:
            raise ValueError("state 的 order 为空时 cursor 必须为 0")
    else:
        if epoch == epochs:
            raise ValueError(
                "state 的 epoch 已等于 epochs（%d），order 必须为空"
                % epochs
            )
        if len(order) != n_samples:
            raise ValueError(
                "state 的 order 长度 %d 必须等于样本数 %d"
                % (len(order), n_samples)
            )
        if sorted(order) != list(range(n_samples)):
            raise ValueError(
                "state 的 order 必须恰是 0..%d 的一个全排列"
                % (n_samples - 1)
            )
        if len(node) == 4:
            if cursor <= 0 or cursor >= n_samples or cursor % group_span != 0:
                raise ValueError(
                    "四元 state 的 cursor %d 必须是小于 N（%d）的 "
                    "microbatch_size*accum_steps（%d）正倍数（更新边界）"
                    % (cursor, n_samples, group_span)
                )
        else:
            if (
                cursor <= 0 or cursor >= n_samples
                or cursor % microbatch_size != 0
            ):
                raise ValueError(
                    "八元 state 的 cursor %d 必须是小于 N（%d）的 "
                    "microbatch_size（%d）正倍数（微批边界）"
                    % (cursor, n_samples, microbatch_size)
                )

    if len(node) == 4:
        return (epoch, order, cursor, rng)

    pending_samples = _parse_json_int(
        node[4], "state 的 pending_samples"
    )
    if pending_samples <= 0:
        raise ValueError("state 的 pending_samples 必须是正整数")
    pending_micro = _parse_json_int(
        node[5], "state 的 pending_microbatches"
    )
    if not (1 <= pending_micro < accum_steps):
        raise ValueError(
            "state 的 pending_microbatches 必须满足 1 <= "
            "pending_microbatches < accum_steps（%d）" % accum_steps
        )
    pending_loss_node = node[6]
    if not isinstance(pending_loss_node, str):
        raise TypeError(
            "state 的 pending_loss 必须是 JSON 字符串，得到 %s"
            % type(pending_loss_node).__name__
        )
    if _HEX_FLOAT_RE.match(pending_loss_node) is None:
        raise ValueError(
            "state 的 pending_loss 含非法十六进制浮点：%r"
            % pending_loss_node
        )
    try:
        pending_loss = float.fromhex(pending_loss_node)
    except ValueError:
        raise ValueError(
            "state 的 pending_loss 含非法十六进制浮点：%r"
            % pending_loss_node
        )
    except OverflowError:
        raise ValueError(
            "state 的 pending_loss 十六进制浮点越界：%r"
            % pending_loss_node
        )
    if not math.isfinite(pending_loss):
        raise ValueError("state 的 pending_loss 必须是有限值（拒绝 NaN/inf）")
    canonical = pending_loss.hex()
    if canonical == "-0x0.0p+0":
        canonical = "0x0.0p+0"
    if canonical != pending_loss_node:
        raise ValueError(
            "state 的 pending_loss 含非规范十六进制浮点：%r"
            % pending_loss_node
        )

    pending_grads = _parse_deep_adam_moments(
        node[7], "state 的 pending_grads"
    )
    grad_names = (
        "conv weights", "conv bias", "groupnorm gamma", "groupnorm beta",
        "linear1 weights", "linear1 bias", "linear2 weights",
        "linear2 bias",
    )
    for grad_tree, ref_tree, gname in zip(
        pending_grads, param_refs, grad_names
    ):
        _check_pending_grad_tree(grad_tree, ref_tree, gname)

    pending_span = cursor % group_span if order else 0
    if pending_samples != pending_span:
        raise ValueError(
            "state 的 pending_samples（%d）与 cursor（%d）相对最近更新"
            "边界的组内样本数（%d）不一致"
            % (pending_samples, cursor, pending_span)
        )
    if pending_micro * microbatch_size != pending_samples:
        raise ValueError(
            "state 的 pending_microbatches（%d）× microbatch_size"
            "（%d）与 pending_samples（%d）不一致"
            % (pending_micro, microbatch_size, pending_samples)
        )

    return (
        epoch, order, cursor, rng, pending_samples, pending_micro,
        pending_loss, tuple(pending_grads),
    )

